    local upgradePart = holder:FindFirstChild(S(151))
    return upgradePart and upgradePart:FindFirstChildWhichIsA(S(34))
end
local autoUpgrade = {}
local connection = nil
function autoUpgrade.SetEnabled(enabled)
    if enabled == autoUpgrade.IsEnabled() then
        return
    end
    if not enabled then
        connection:Disconnect()
        connection = nil
        log(S(217))
        return
    end
    log(S(65))
    local lastFire = 0
    connection = RunService.Heartbeat:Connect(function()
        local now = tick()
        if now - lastFire < FIRE_INTERVAL then
            return
        end
        lastFire = now
        local plot = getCurrentPlot()
        if not plot then
            return
        end
        local parts = getPlotParts(plot)
        if not parts.Holders then
            return
        end
        for _, holder in ipairs(parts.Holders:GetChildren()) do
            local detector = findUpgradeClickDetector(holder)
            if detector then
                fireclickdetector(detector)
            end
        end
    end)
end
function autoUpgrade.IsEnabled()
    return connection ~= nil
end
return autoUpgrade
end
end
modules[S(334)] = function()
local function dumpInstance(instance, log, indent)
    indent = indent or S(252)
    for _, child in ipairs(instance:GetChildren()) do
        local line = indent .. child.ClassName .. S(131) .. child.Name .. S(205)
        if child:IsA(S(406)) then
            line = line .. string.format(
                S(238),
                child.ActionText, child.ObjectText, tostring(child.HoldDuration)
            )
        elseif child:IsA(S(4)) then
            line = line .. string.format(S(304), tostring(child.MaxActivationDistance))
        elseif child:IsA(S(326)) or child:IsA(S(324)) then
            line = line .. S(396)
        end
        log(line)
        for attrName, attrValue in pairs(child:GetAttributes()) do
            log(indent .. S(21) .. attrName .. S(79) .. tostring(attrValue))
        end
        dumpInstance(child, log, indent .. S(200))
    end
end
return dumpInstance
end
